<template>
<section id="submarine-map" class="cable-module">
 <header class="module-header"><div><small>NETWORK ATLAS / 01</small><h2>海底光缆地图</h2></div><button :aria-expanded="opened" aria-controls="cable-content" @click="opened=!opened">{{opened?'收起地图':'探索海底网络'}}</button></header>
 <div v-if="opened" id="cable-content">
 <p class="intro">互联网的另一面，在海洋之下。选择一条线路，探索跨洲连接与登陆地区。</p>
 <div class="toolbar"><input v-model="query" aria-label="搜索海底光缆" placeholder="搜索线路、国家或登陆地区…"/><select v-model="region" aria-label="光缆海域"><option value="">全部海域</option><option>大西洋</option><option>太平洋</option><option>非洲沿岸</option></select><span>{{visible.length}} / {{cables.length}} 条精选线路</span></div>
 <div class="atlas-layout"><div class="map-column"><div class="map-controls"><button aria-label="放大光缆地图" @click="zoom(1.4)">＋</button><button aria-label="缩小光缆地图" @click="zoom(1/1.4)">−</button><button @click="reset">重置视图</button><label><input v-model="showPoints" type="checkbox"/>登陆地区</label></div>
 <svg ref="map" class="atlas" viewBox="0 0 1080 540" role="img" aria-label="海底光缆连接示意地图，可拖动与缩放" @pointerdown="startDrag" @pointermove="drag" @pointerup="endDrag" @pointercancel="endDrag" @wheel.prevent="wheel">
 <rect width="1080" height="540" fill="#0a1c2b"/><g :transform="`translate(${offsetX} ${offsetY}) scale(${scale})`">
 <path v-for="n in 11" :key="'v'+n" :d="`M${n*90} 0V540`" class="grid"/><path v-for="n in 5" :key="'h'+n" :d="`M0 ${n*90}H1080`" class="grid"/>
 <path v-for="(d,i) in land" :key="i" :d="d" class="land"/>
 <g v-for="c in visible" :key="c.id" :opacity="selected===c.id?1:.48"><path v-for="(d,i) in paths(c.points)" :key="i" :d="d" fill="none" :stroke="c.color" :stroke-width="selected===c.id?3:1.6" vector-effect="non-scaling-stroke"/><path v-for="(d,i) in paths(c.points)" :key="'hit'+i" :d="d" fill="none" stroke="transparent" stroke-width="16" vector-effect="non-scaling-stroke" class="route-hit" @click.stop="choose(c.id)"><title>{{c.name}} · {{c.region}}</title></path>
 <template v-if="showPoints"><circle v-for="(p,i) in c.points" :key="'p'+i" :cx="project(p.lon,p.lat)[0]" :cy="project(p.lon,p.lat)[1]" :r="3/scale" :fill="c.color"><title>{{p.name}} · {{c.name}}</title></circle></template></g>
 </g><text x="20" y="520" fill="#89a7b9" font-size="11">SCHEMATIC CONNECTIONS · NOT SURVEYED ROUTES</text></svg>
 <p v-if="mapError" role="status">{{mapError}} <button @click="loadLand">重新加载底图</button></p><p class="caption">拖动平移 · 滚轮或按钮缩放 · 点击线路查看详情。地图连线为原创连接示意，并非实际海床走向。</p>
 </div><aside class="details"><span class="eyebrow">CABLE DIRECTORY</span><div class="cable-list"><button v-for="c in visible" :key="c.id" :aria-pressed="selected===c.id" @click="choose(c.id)"><i :style="{background:c.color}"/>{{c.name}}<small>{{c.region}}</small></button><p v-if="!visible.length">没有匹配线路，请调整关键词或海域。</p></div>
 <article v-if="current"><h3>{{current.name}}</h3><p>{{current.note}}</p><h4>精选登陆地区</h4><ul><li v-for="p in current.points" :key="p.name">{{p.name}}</li></ul><a :href="current.source" target="_blank" rel="noopener noreferrer">查看线路资料 ↗</a></article></aside></div>
 <footer>教育示意版 · {{cables.length}} 条精选系统，非全球完整目录；位置为城市级近似值，不表示实时运行、故障或流量。资料入口：<a href="https://www.submarinecablemap.com/" target="_blank" rel="noopener noreferrer">TeleGeography</a>；陆地底图：<a href="https://www.naturalearthdata.com/" target="_blank" rel="noopener noreferrer">Natural Earth（公共领域）</a>。</footer>
 </div>
</section>
</template>
<script>
import {cables,project,connectionPaths,landPaths,filterCables} from '../utils/submarine-cables.mjs';
export default {name:'SubmarineCableMap',data:()=>({opened:false,cables,query:'',region:'',selected:'marea',showPoints:true,land:[],mapError:'',scale:1,offsetX:0,offsetY:0,dragging:null,controller:null}),computed:{visible(){return filterCables(this.query,this.region);},current(){return this.visible.find(c=>c.id===this.selected)||this.visible[0];}},watch:{opened(value){if(value&&!this.land.length)this.loadLand();},visible(items){if(!items.some(c=>c.id===this.selected))this.selected=items[0]?.id||'';}},beforeUnmount(){this.controller?.abort();},methods:{project,paths:connectionPaths,async loadLand(){this.controller?.abort();this.controller=new AbortController();this.mapError='';try{const r=await fetch(`${process.env.BASE_URL}maps/land.geojson`,{signal:this.controller.signal});if(!r.ok)throw new Error();this.land=landPaths(await r.json());}catch(e){if(e.name!=='AbortError')this.mapError='陆地底图加载失败，线路仍可查看。';}},choose(id){this.selected=id;},zoom(factor){const next=Math.min(6,Math.max(1,this.scale*factor));const ratio=next/this.scale;this.offsetX=540-(540-this.offsetX)*ratio;this.offsetY=270-(270-this.offsetY)*ratio;this.scale=next;this.clamp();},clamp(){this.offsetX=Math.min(0,Math.max(1080*(1-this.scale),this.offsetX));this.offsetY=Math.min(0,Math.max(540*(1-this.scale),this.offsetY));},reset(){this.scale=1;this.offsetX=0;this.offsetY=0;},wheel(e){this.zoom(e.deltaY<0?1.15:1/1.15);},startDrag(e){if(e.button!==0)return;this.dragging={x:e.clientX,y:e.clientY,ox:this.offsetX,oy:this.offsetY};},drag(e){if(!this.dragging)return;const ratio=1080/this.$refs.map.getBoundingClientRect().width;this.offsetX=this.dragging.ox+(e.clientX-this.dragging.x)*ratio;this.offsetY=this.dragging.oy+(e.clientY-this.dragging.y)*ratio;this.clamp();},endDrag(){this.dragging=null;}}};
</script>
<style scoped>
.cable-module{margin:24px 20px;padding:22px;border:1px solid var(--el-border-color,#d7e4dc);border-radius:14px;background:var(--el-bg-color,#fff);color:var(--el-text-color-primary,#273b30);scroll-margin-top:90px;font-size:13px}.module-header,.toolbar,.map-controls{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap}.module-header h2{font-size:20px;margin:5px 0}.module-header small,.eyebrow{font:10px Consolas,monospace;letter-spacing:2px;opacity:.6}button,input,select{font:inherit;color:inherit;background:var(--el-bg-color,#fff);border:1px solid var(--el-border-color,#d7e4dc);border-radius:7px;padding:9px;box-sizing:border-box;max-width:100%}button{cursor:pointer}button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid var(--ui-accent,#398c5a);outline-offset:2px}.toolbar{justify-content:flex-start;margin:18px 0}.toolbar>input{flex:1;min-width:160px}.toolbar span{font-size:11px;opacity:.65}.atlas-layout{display:grid;grid-template-columns:minmax(0,1fr) 255px;gap:18px}.map-column{min-width:0}.map-controls{justify-content:flex-start;margin-bottom:10px}.map-controls label{display:flex;gap:6px;align-items:center}.atlas{display:block;width:100%;border:1px solid #254354;border-radius:12px;touch-action:none;cursor:grab;aspect-ratio:2}.atlas:active{cursor:grabbing}.grid{stroke:#193546;stroke-width:.6;fill:none}.land{fill:#203c49;stroke:#365563;stroke-width:.6}.route-hit{cursor:pointer}.details{padding:16px;background:var(--ui-accent-soft,#edf6ef);border-radius:12px}.cable-list{display:grid;gap:4px;margin-top:12px;max-height:230px;overflow:auto}.cable-list button{display:flex;align-items:center;gap:8px;text-align:left;border-color:transparent}.cable-list button[aria-pressed=true]{border-color:var(--ui-accent,#398c5a)}.cable-list i{width:8px;height:8px;border-radius:50%;flex-shrink:0}.cable-list small{margin-left:auto;font-size:10px;opacity:.65}h3{font-size:22px;margin-bottom:8px}h4{margin-bottom:6px}article p,li{line-height:1.8}ul{padding-left:18px}a{color:var(--ui-accent,#347a50)}.intro,.caption,footer{line-height:1.8}.caption,footer{font-size:11px;opacity:.75}footer{margin-top:15px;border-top:1px solid var(--el-border-color,#d7e4dc);padding-top:12px}@media(max-width:1000px){.atlas-layout{grid-template-columns:1fr}.cable-list{grid-template-columns:repeat(auto-fit,minmax(145px,1fr))}}@media(max-width:600px){.cable-module{margin:16px 12px;padding:14px}.toolbar>input{width:100%;flex-basis:100%}.atlas{min-height:240px}.details{padding:12px}}
</style>
